{"sql": "-- Create the stored procedure for generating monthly reports
CREATE OR REPLACE FUNCTION employees.generate_monthly_report(report_date DATE)
RETURNS INTEGER AS $$
DECLARE
    new_report_id INTEGER;
    dept_count INTEGER;
    total_emp INTEGER;
    avg_sal DECIMAL(10,2);
BEGIN
    -- Get current statistics
    SELECT 
        COUNT(DISTINCT d.id),
        COUNT(DISTINCT e.id),
        COALESCE(ROUND(AVG(s.amount), 2), 0)
    INTO dept_count, total_emp, avg_sal
    FROM employees.department d
    LEFT JOIN employees.department_employee de ON d.id = de.department_id AND de.to_date = '9999-01-01'
    LEFT JOIN employees.employee e ON de.employee_id = e.id
    LEFT JOIN employees.salary s ON e.id = s.employee_id AND s.to_date = '9999-01-01';

    -- Insert the report record
    INSERT INTO employees.monthly_reports (report_date, department_count, total_employees, avg_salary)
    VALUES (report_date, dept_count, total_emp, avg_sal)
    RETURNING report_id INTO new_report_id;

    RETURN new_report_id;
END;
$$ LANGUAGE plpgsql;"}

{"sql": "-- Create the trigger function for high salary alerts
CREATE OR REPLACE FUNCTION employees.high_salary_alert_function()
RETURNS TRIGGER AS $$
BEGIN
    -- Check if the new salary is greater than 120000
    IF NEW.amount > 120000 THEN
        INSERT INTO employees.salary_alerts (employee_id, salary_amount)
        VALUES (NEW.employee_id, NEW.amount);
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;"}

